            sliceEnd = now + SLICE_SECONDS
        end
        if currentTask then
            local ok, err = pcall(currentTask.step)
            if not ok then
                log(S(138) .. currentTask.name .. S(24) .. tostring(err))
            end
        end
    end)
end
